  @Test
  public void fromSecretSeedTestUsingCharArray() {
    KeyPair keyPair = KeyPair.fromSecretSeed("SGUZP5NW".toCharArray());
    assertNotNull(keyPair);
    assertTrue(keyPair.canSign());
  }

  @Test
  public void fromSecretSeedTestUsingString() {
